void cRSubGame::BuildLevel()
{
    int runtime_build_seed;

    if (selected_level_record_active != 0) {
        SubSolution* record = selected_level_record;
        runtime_build_seed = record->runtime_build_seed;
    } else {
        int mode = level_mode;
        if (mode == 4 || mode == 7) {
            runtime_build_seed = 0;
        } else {
            runtime_build_seed = (int)RAND(32768.0f, "Seed");
        }
    }

    int mode = level_mode;
    switch (mode) {
    case 0:
        current_high_score_record.ReSet(
            runtime_build_seed,
            level_mode_arg,
            level_arg_tail,
            runtime_flags,
            0,
            level_mode_arg);
        break;
    case 1:
        current_high_score_record.ReSet(
            runtime_build_seed,
            level_mode_arg,
            level_arg_tail,
            runtime_flags,
            1,
            level_mode_arg);
        break;
    case 4:
        current_high_score_record.ReSet(
            runtime_build_seed,
            level_mode_arg,
