            int lane_and_flags = *lane_word;
            lane_and_flags &= 0xffff5fff;
            *lane_word = lane_and_flags;
            *tile_flags = 0;
            *(short*)cell_flags = 0;
            *lane_word &= 0xffffafa7;
            *(short*)cell_flags = 0;
