                    *(float*)(cell + CELL_RENDER_ARG_1C) = (float)lane_uv * 0.125f;
                    int row_uv = build_row % 8;
                    *(float*)(cell + CELL_RENDER_ARG_20) = (float)row_uv * 0.125f;
