                    || tile == SUBLOC_TILE_SLIDE_O
                    || tile == SUBLOC_TILE_HEALTH_PICKUP
                    || tile == SUBLOC_TILE_SPEEDUP_PICKUP
                    || tile == SUBLOC_TILE_JETPACK_PICKUP
                    || tile == SUBLOC_TILE_SLIDE_VARIANT_1A
